package com.bridge.quartercore;
import org.junit.jupiter.api.Test;import java.time.*;import static org.junit.jupiter.api.Assertions.*;import static com.bridge.quartercore.InitialCutoverOperatorControllerTest.*;import static com.bridge.quartercore.InitialCutoverOperatorController.Stage.*;
class OperatorCheckpointTest {
 static class CheckOps extends Ops {int checks;boolean mismatch;Runnable checking=()->{}; public void checkpointRead(InitialCutoverOperatorController.Stage next,String who,String token,Runnable guard){guard.run();checks++;assertEquals("a".repeat(64),token);checking.run();if(mismatch)throw new NativeSheetsModel.Rejected();guard.run();}}
 static void finish(InitialCutoverOperatorController c,String cookie,InitialCutoverOperatorController.Stage s){var p=preview(c,cookie,s);c.execute(s,cookie,proof(c,cookie,s.name().toLowerCase()+"-execute"),p.digest(),true);}
 @Test void twoFreshScopesAfterExpiryRotateCookieAndNeverExtendLocator(){var t=new CrossQuarterNativeSettlementTest.Time();t.now=Instant.now();var ops=new CheckOps();var c=controller(ops,t);String first=c.session().cookie();prepare(c,first);finish(c,first,METADATA);Runnable old=ops.savedGuard;t.now=t.now.plusSeconds(301);String proof=proof(c,first,"checkpoint");String second=c.checkpoint(first,proof).cookie();assertNotEquals(first,second);assertThrows(RuntimeException.class,old::run);assertThrows(RuntimeException.class,()->c.challenge(first,"history-preview"));assertTrue(c.cookieSeconds()<1500);finish(c,second,HISTORY);t.now=t.now.plusSeconds(301);String third=c.checkpoint(second,proof(c,second,"checkpoint")).cookie();finish(c,third,ACTIVATE);assertEquals(2,ops.checks);assertEquals(3,ops.writes);assertThrows(RuntimeException.class,()->c.challenge(third,"checkpoint"));assertTrue(c.cookieSeconds()<1200);}
 @Test void freshReadMismatchIsTerminalWithoutAnotherWrite(){var t=new CrossQuarterNativeSettlementTest.Time();var ops=new CheckOps();var c=controller(ops,t);String k=c.session().cookie();prepare(c,k);finish(c,k,METADATA);ops.mismatch=true;String p=proof(c,k,"checkpoint");assertThrows(RuntimeException.class,()->c.checkpoint(k,p));assertEquals(1,ops.writes);assertThrows(RuntimeException.class,()->c.challenge(k,"checkpoint"));}
 @Test void readScopeExpiresDuringReadAndOldProofCannotBeReused(){var t=new CrossQuarterNativeSettlementTest.Time();var ops=new CheckOps();var c=controller(ops,t);String k=c.session().cookie();prepare(c,k);finish(c,k,METADATA);ops.checking=()->t.now=t.now.plusSeconds(121);String p=proof(c,k,"checkpoint");assertThrows(RuntimeException.class,()->c.checkpoint(k,p));assertThrows(RuntimeException.class,()->c.checkpoint(k,p));assertEquals(1,ops.checks);assertEquals(1,ops.writes);}
 @Test void unknownAndOutstandingPreviewCannotRenew(){var t=new CrossQuarterNativeSettlementTest.Time();var ops=new CheckOps();var c=controller(ops,t);String k=c.session().cookie();prepare(c,k);finish(c,k,METADATA);var h=preview(c,k,HISTORY);assertThrows(RuntimeException.class,()->c.challenge(k,"checkpoint"));ops.unknown=true;String p=proof(c,k,"history-execute");assertThrows(RuntimeException.class,()->c.execute(HISTORY,k,p,h.digest(),true));assertThrows(RuntimeException.class,()->c.challenge(k,"checkpoint"));assertEquals(0,ops.checks);}
 @Test void scopeDisplayNeverOutlivesAbsoluteLocator(){var t=new CrossQuarterNativeSettlementTest.Time();var ops=new CheckOps();var c=controller(ops,t);Instant initial=t.now;String k=c.session().cookie();prepare(c,k);finish(c,k,METADATA);t.now=t.now.plusSeconds(1700);var renewed=c.checkpoint(k,proof(c,k,"checkpoint"));assertEquals(initial.plusSeconds(1800),renewed.expires());assertEquals(100,c.cookieSeconds());}
 @Test void locatorAbsoluteExpiryCannotBeRenewed(){var t=new CrossQuarterNativeSettlementTest.Time();var ops=new CheckOps();var c=controller(ops,t);String k=c.session().cookie();prepare(c,k);finish(c,k,METADATA);t.now=t.now.plusSeconds(1801);assertThrows(RuntimeException.class,()->c.challenge(k,"checkpoint"));assertEquals(0,ops.checks);}
}
